import { inspect } from 'node:util';
import { redactSecrets } from '@jini-ai/core';
import { createHash } from "node:crypto";

import type { Request, RequestHandler } from "express";

import type { CommentRateLimiter } from "../ingress.js";
import type { CommentSubmission } from "../types.js";

/**
 * @file ADR-031 §4 (SPEC-033) — the public, unauthenticated comment submission route. The ONLY
 * route a hostile visitor can reach into the Comments plugin; everything downstream of this file
 * is `CommentIngressPolicy` (rate-limit, honeypot, sanitize, spam-classify — see `comments/ingress.ts`).
 *
 * `authorIpHash` is computed HERE, at the HTTP boundary, from the raw request IP — the raw IP
 * itself is never passed into `ingressContext` or stored (mirrors `analytics/ingest.ts`'s
 * discard-raw-IP-at-the-boundary discipline). The host provides the salt at construction.
 */
/** The handler needs only the accepted id/status, so a host may dispatch to any stored provider. */
export type CommentSubmitResult = { ok: true; comment: { id: string; status: string } } | { ok: false; reason: string };

export interface CommentSubmitRequired {
  ingressPolicy: { submit: (submission: CommentSubmission) => Promise<CommentSubmitResult> };
  workspaceId: string;
  ipHashSalt: string;
  /** Host-owned HTTP request budget, separate from the ingress policy's submission budget. */
  rateLimiter: CommentRateLimiter;
  /** Host-selected trusted proxy policy; the raw address is hashed only at this boundary. */
  clientIp: (required: { request: Request }, optional?: Record<string, never>) => string;
}

/** The per-request signal bag (honeypot value, IP hash) — split out of `buildCommentSubmission` so
 * that function's own field count stays clear of the complexity ceiling. @complexity O(IP length). */
function buildIngressContext(req: Request, deps: CommentSubmitRequired, body: Record<string, unknown>) {
  // Resolve with the host's trust policy and hash before the address leaves HTTP.
  const ip = deps.clientIp({ request: req }, {});
  return {
    authorIpHash: createHash("sha256").update(`${ip}:${deps.ipHashSalt}`).digest("hex"),
    honeypotValue: typeof body.website === "string" ? body.website : "", // conventional honeypot field name
  };
}

/**
 * Normalizes the untyped request body into a `CommentSubmission`. Every field below defaults or
 * clamps independently (undefined-means-empty for required strings, falsy-means-null for optional
 * ones) — same behavior as before this was a named function, just no longer inline in the handler.
 *
 * @complexity O(1).
 */
function buildCommentSubmission(req: Request, body: Record<string, unknown>, deps: CommentSubmitRequired): CommentSubmission {
  return {
    workspaceId: deps.workspaceId,
    entryId: String(body.entryId ?? ""),
    parentId: body.parentId ? String(body.parentId) : null,
    authorName: String(body.authorName ?? "").slice(0, 200),
    authorEmail: body.authorEmail ? String(body.authorEmail).slice(0, 320) : null,
    authorUrl: body.authorUrl ? String(body.authorUrl).slice(0, 2000) : null,
    bodyRaw: String(body.body ?? ""),
    authorPrincipalId: null, // v1: anonymous-only public route; member-attributed submission is a named deferral
    ingressContext: buildIngressContext(req, deps, body),
  };
}

/** Refuses a missing or empty string dep by name. @throws {TypeError} When `value` is not a non-empty string. @complexity O(1). */
function requireNonEmptyString(required: { name: "workspaceId" | "ipHashSalt"; value: unknown }, _optional: Record<string, never>): void {
  if (typeof required.value !== "string" || required.value.length === 0) {
    throw new TypeError(`comments submit handler requires ${required.name}`);
  }
}

/** Construction-time refusal of a missing or invalid required port. @throws {TypeError} Naming the first bad dep. @complexity O(1). */
function assertSubmitDeps(deps: CommentSubmitRequired): void {
  if (typeof deps?.ingressPolicy?.submit !== "function") {
    throw new TypeError("comments submit handler requires ingressPolicy");
  }
  requireNonEmptyString({ name: "workspaceId", value: deps.workspaceId }, {});
  requireNonEmptyString({ name: "ipHashSalt", value: deps.ipHashSalt }, {});
  if (typeof deps.rateLimiter?.check !== "function") {
    throw new TypeError("comments submit handler requires rateLimiter");
  }
  if (typeof deps.clientIp !== "function") {
    throw new TypeError("comments submit handler requires clientIp");
  }
}

/** The no-JS landing fragment. A tripped honeypot lands exactly like an accepted (held) comment, so a bot
 * filling the hidden field learns nothing; a real visitor never fills it, so no human is misled.
 * @complexity O(1). */
function formOutcome(result: CommentSubmitResult): "comment-pending" | "comment-error" {
  return result.ok || result.reason === "honeypot-tripped" ? "comment-pending" : "comment-error";
}

/** Builds the anonymous submission handler; the host owns route mounting and salt policy.
 * @throws {TypeError} When ingressPolicy, workspaceId, ipHashSalt, rateLimiter or clientIp is missing or invalid.
 * @returns An Express handler preserving the source route's normalization and HTTP responses.
 * @complexity O(body length) normalization and hashing plus the ingress port's work.
 */
export function createCommentSubmitHandler(deps: CommentSubmitRequired, optional: {
  formRedirect?: (required: { request: Request }) => string | undefined;
  /** Best-effort notification after ingress accepts; failure cannot undo the committed comment. */
  onAccepted?: (required: { request: Request; submission: CommentSubmission; comment: { id: string; status: string } }) => void | Promise<void>;
} = {}): RequestHandler {
  assertSubmitDeps(deps);
  return async (req, res) => {
    try {
      const body = req.body as Record<string, unknown>;
      const submission = buildCommentSubmission(req, body, deps);
      const rateLimit = await deps.rateLimiter.check({ key: String(submission.ingressContext.authorIpHash) });
      const result: CommentSubmitResult = rateLimit.allowed
        ? await deps.ingressPolicy.submit(submission)
        : { ok: false, reason: "rate-limited" };
      if (result.ok) {
        try { await optional.onAccepted?.({ request: req, submission, comment: result.comment }); }
        catch { /* A notification cannot turn an accepted comment into a failed submission. */ }
      }

      const redirect = optional.formRedirect?.({ request: req });
      if (redirect !== undefined) {
        res.redirect(303, `${redirect}#${formOutcome(result)}`);
        return;
      }
      if (!result.ok) {
        // No oracle: every rejection reason maps to the SAME generic 422, distinguishable only in
        // the response body's `reason` for legitimate client-side form UX, never a status-code tell.
        res.status(422).json({ error: "comment was not accepted", reason: result.reason });
        return;
      }

      res.status(201).json({ id: result.comment.id, status: result.comment.status });
    } catch (err) {
      // Public, unauthenticated route (this file's own header) — any visitor's malformed or
      // hostile submission must still get a fast, honest response, never a hang; an unguarded
      // failure here is reachable by anyone, not just an authenticated admin.
      console.error("[site/comments-submit] unexpected error", redactSecrets({ input: inspect(err) }, { redactPii: false }));
      res.status(500).json({ error: "internal error", code: "INTERNAL_ERROR" });
    }
  };
}

import { loadOptionalPeer } from '@jini-ai/core/optional-peer';
import { MediaValidationError } from './types.js';

/** Shared 50 MiB document limit for admission, extraction and host upload policy. */
export const MAX_DOCUMENT_BYTES = 50 * 1024 * 1024;
export const DOCUMENT_CONTENT_TYPES = {
  md: 'text/markdown', txt: 'text/plain', csv: 'text/csv', json: 'application/json',
  doc: 'application/msword', xls: 'application/vnd.ms-excel', rtf: 'application/rtf',
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  pages: 'application/vnd.apple.pages', key: 'application/vnd.apple.keynote',
  pdf: 'application/pdf', docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
} as const;

/** Streaming archive port: the existing host archive adapter supplies entries; never extract to disk.
 * File entries must include their ZIP compressed size for ratio checks.
 * Adapters must reject encryption and report links/special files rather than following them. */
export interface DocumentArchiveReaderPort {
  entries(required: { archive: Uint8Array }, optional?: Record<string, never>): AsyncIterable<{
    kind: string; entryPath: string; declaredSize?: number | undefined; compressedSize?: number | undefined;
    openReadStream?: (required: Record<string, never>, optional?: Record<string, never>) => AsyncIterable<Uint8Array>;
  }>;
}

function invalid(message: string): never { throw new MediaValidationError({ message }); }

/** Names are display metadata only. Refuse path syntax rather than trying to normalize it. */
export function documentContentType(required: { filename: string }, _optional: Record<string, never> = {}): string {
  const name = required.filename;
  if (!name.trim() || name.length > 255 || /[\\/\u0000-\u001f\u007f]/u.test(name)) invalid('document filename must be a plain filename of at most 255 characters');
  const dot = name.lastIndexOf('.');
  if (dot <= 0) invalid('document filename must include an allowed extension');
  const extension = name.slice(dot + 1).toLowerCase();
  if (!Object.hasOwn(DOCUMENT_CONTENT_TYPES, extension)) invalid(`document type must be ${Object.keys(DOCUMENT_CONTENT_TYPES).map(ext => '.' + ext).join(', ')}`);
  return DOCUMENT_CONTENT_TYPES[extension as keyof typeof DOCUMENT_CONTENT_TYPES];
}

/** Fatal decoding and control checks reject binary content disguised with a text extension. */
export function decodeDocumentUtf8(required: { bytes: Uint8Array }, _optional: Record<string, never> = {}): string {
  let text: string;
  try { text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(required.bytes); }
  catch { return invalid('document text must be valid UTF-8'); }
  if (/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f-\u009f]/u.test(text)) invalid('document text contains binary controls');
  return text;
}

const MAX_DOCUMENT_COMPRESSION_RATIO = 100;

/** OOXML variants share the archive policy; only the main part and XML contract differ. */
const OFFICE_PACKAGES = {
  docx: { part: 'word/document.xml', root: 'document', family: 'wordprocessingml', mainType: 'wordprocessingml.document', label: 'Word' },
  xlsx: { part: 'xl/workbook.xml', root: 'workbook', family: 'spreadsheetml', mainType: 'spreadsheetml.sheet', label: 'Excel' },
  pptx: { part: 'ppt/presentation.xml', root: 'presentation', family: 'presentationml', mainType: 'presentationml.presentation', label: 'PowerPoint' },
} as const;
type OfficeExtension = keyof typeof OFFICE_PACKAGES;
type ArchiveExtension = OfficeExtension | 'pages' | 'key';

type ArchiveEntry = DocumentArchiveReaderPort['entries'] extends (...args: never[]) => AsyncIterable<infer Entry> ? Entry : never;
const MAX_ARCHIVE_ENTRIES = 2048;
const MAX_EXPANDED_BYTES = 40 * 1024 * 1024;
const isArchiveExtension = (extension: string): extension is ArchiveExtension => extension in OFFICE_PACKAGES || extension === 'pages' || extension === 'key';

/** Running state for one archive walk: names seen, captured OOXML members and observed totals. */
interface ArchiveScan {
  readonly label: string;
  readonly extension: ArchiveExtension;
  readonly office: (typeof OFFICE_PACKAGES)[OfficeExtension] | undefined;
  readonly archiveBytes: number;
  readonly names: Set<string>;
  readonly members: Map<string, string>;
  count: number;
  total: number;
  iworkMarker: boolean;
}

const isUnsafeArchivePath = (path: string) => !path || /[\\:\u0000-\u001f\u007f]/u.test(path) || path.startsWith('/') ||
  path.split('/').some(part => !part || part === '.' || part === '..');
const isMacroPayload = (path: string, extension: ArchiveExtension) =>
  /vba|macro|activex|(^|\/)embeddings\//i.test(path) || /\.(exe|dll)$/i.test(path) || (extension === 'docx' && /\.bin$/i.test(path));

/** Path policy applies to directories too; a case-folded duplicate could shadow a checked member. */
function assertArchivePath(scan: ArchiveScan, path: string): void {
  if (isUnsafeArchivePath(path)) invalid(`${scan.label} contains an unsafe archive path`);
  const folded = path.toLowerCase();
  if (scan.names.has(folded)) invalid(`${scan.label} contains duplicate archive paths`);
  scan.names.add(folded);
  if (isMacroPayload(path, scan.extension)) invalid(`${scan.label} contains a macro or embedded payload`);
}

/** Header sizes are checked before any byte is read; observed bytes are checked again while streaming. */
function assertDeclaredSizes(scan: ArchiveScan, entry: ArchiveEntry): asserts entry is ArchiveEntry & { declaredSize: number; compressedSize: number; openReadStream: NonNullable<ArchiveEntry['openReadStream']> } {
  if (entry.kind !== 'file' || !entry.openReadStream) invalid(`${scan.label} contains a link or special entry`);
  if (!Number.isSafeInteger(entry.declaredSize) || entry.declaredSize! < 0 || scan.total + entry.declaredSize! > MAX_EXPANDED_BYTES) invalid(`${scan.label} expanded size exceeds its limit`);
  if (!Number.isSafeInteger(entry.compressedSize) || entry.compressedSize! < 0 || entry.compressedSize! > scan.archiveBytes) invalid(`${scan.label} archive compressed size is invalid`);
}

/** Streams one file entry, enforcing size and ratio limits per chunk; buffers only captured members. */
async function readArchiveFile(scan: ArchiveScan, entry: ArchiveEntry & { declaredSize: number; compressedSize: number; openReadStream: NonNullable<ArchiveEntry['openReadStream']> },
  { capture }: { capture: boolean }): Promise<Uint8Array[]> {
  let size = 0;
  const chunks: Uint8Array[] = [];
  for await (const chunk of entry.openReadStream({})) {
    scan.total += chunk.byteLength; size += chunk.byteLength;
    if (scan.total > MAX_EXPANDED_BYTES || size > entry.declaredSize) invalid(`${scan.label} expanded size exceeds its limit`);
    // 100:1 permits ordinary Office XML but cuts off cheap decompression bombs even below
    // the absolute cap. Check observed bytes before buffering; entry limits resist ZIP padding.
    if (size > entry.compressedSize * MAX_DOCUMENT_COMPRESSION_RATIO ||
      scan.total > scan.archiveBytes * MAX_DOCUMENT_COMPRESSION_RATIO) invalid(`${scan.label} compression ratio exceeds 100:1`);
    if (capture) chunks.push(chunk);
  }
  if (size !== entry.declaredSize) invalid(`${scan.label} archive entry size is incorrect`);
  return chunks;
}

/** Reader failures (corrupt or encrypted ZIPs) are reported by application, never as ZIP jargon. */
function archiveApplication({ office, extension }: ArchiveScan): string {
  if (office) return office.label;
  return extension === 'pages' ? 'Pages' : 'Keynote';
}

async function scanArchiveEntry(scan: ArchiveScan, entry: ArchiveEntry): Promise<void> {
  ++scan.count;
  if (scan.count > MAX_ARCHIVE_ENTRIES) invalid(`${scan.label} has too many archive entries`);
  const name = entry.entryPath;
  const path = name.endsWith('/') ? name.slice(0, -1) : name;
  assertArchivePath(scan, path);
  if (entry.kind === 'directory') return;
  assertDeclaredSizes(scan, entry);
  const capture = !!scan.office && ['[Content_Types].xml', '_rels/.rels', scan.office.part].includes(path);
  const chunks = await readArchiveFile(scan, entry, { capture });
  if (path === 'Index/Document.iwa' || path === 'Index.zip') scan.iworkMarker = true;
  if (capture) scan.members.set(path, decodeDocumentUtf8({ bytes: Buffer.concat(chunks) }));
}

/** Validate every entry, not just required members: hidden payloads and combined expansion matter.
 * 2048 entries / 40 MiB expanded bound both metadata work and decompression, before any persistence.
 * O(expanded bytes + entries) work/space, bounded independently of compressed upload size. */
async function validateDocumentArchive(required: { bytes: Uint8Array; extension: ArchiveExtension; archiveReader?: DocumentArchiveReaderPort | undefined },
  _optional: Record<string, never> = {}): Promise<void> {
  const label = required.extension.toUpperCase();
  const office = required.extension in OFFICE_PACKAGES ? OFFICE_PACKAGES[required.extension as OfficeExtension] : undefined;
  if (!required.archiveReader) invalid(`${label} validation requires an archive reader`);
  const scan: ArchiveScan = {
    label, extension: required.extension, office, archiveBytes: required.bytes.byteLength,
    names: new Set(), members: new Map(), count: 0, total: 0, iworkMarker: false
  };
  try {
    for await (const entry of required.archiveReader.entries({ archive: required.bytes })) await scanArchiveEntry(scan, entry);
  } catch (error) {
    if (error instanceof MediaValidationError) throw error;
    invalid(`This file isn't a valid ${archiveApplication(scan)} file (or it's password-protected).`);
  }
  if (office) await validateOfficePackage({ members: scan.members, extension: required.extension as OfficeExtension });
  else if (!scan.iworkMarker) invalid(`${label} is missing its required iWork package members`);
  else {
    // A non-Office archive with its iWork marker has passed this package-shape check.
  }
}

const CONTENT_TYPES_NAMESPACE = 'http://schemas.openxmlformats.org/package/2006/content-types';
const RELATIONSHIPS_NAMESPACE = 'http://schemas.openxmlformats.org/package/2006/relationships';
// eslint-disable-next-line sonarjs/no-clear-text-protocols -- These are OOXML namespace/relationship identifiers, never network request URLs; changing their schemes breaks format validation.
const OFFICE_DOCUMENT_RELATIONSHIPS = ['http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument', 'http://purl.oclc.org/ooxml/officeDocument/relationships/officeDocument'];
type OfficeSpec = (typeof OFFICE_PACKAGES)[OfficeExtension];

/** The content-types Override must name the main part with this format's main content type. */
const hasMainOverride = (typesRoot: Element, spec: OfficeSpec) => [...typesRoot.children].some(node => node.localName === 'Override' && node.namespaceURI === CONTENT_TYPES_NAMESPACE &&
  node.getAttribute('PartName') === '/' + spec.part && node.getAttribute('ContentType') === `application/vnd.openxmlformats-officedocument.${spec.mainType}.main+xml`);
/** The package relationship must point at the internal main part as the office document. */
const hasOfficeDocumentRelationship = (relsRoot: Element, spec: OfficeSpec) => [...relsRoot.children].some(node => {
  if (node.localName !== 'Relationship' || node.namespaceURI !== RELATIONSHIPS_NAMESPACE) return false;
  return [spec.part, '/' + spec.part].includes(node.getAttribute('Target') ?? '') && node.getAttribute('TargetMode') !== 'External' &&
    OFFICE_DOCUMENT_RELATIONSHIPS.includes(node.getAttribute('Type') ?? '');
});
const isOfficeMainRoot = (root: Element, spec: OfficeSpec) => root.localName === spec.root &&
  [`http://schemas.openxmlformats.org/${spec.family}/2006/main`, `http://purl.oclc.org/ooxml/${spec.family}/main`].includes(root.namespaceURI ?? '');

function assertOfficeXml({ documents: [types, rels, document], spec, label }: { documents: readonly Document[]; spec: OfficeSpec; label: string }): void {
  if ([types!, rels!, document!].some(xml => xml.querySelector('parsererror'))) invalid(`${label} contains invalid package XML`);
  const typesRoot = types!.documentElement;
  const relsRoot = rels!.documentElement;
  // Package markers count only as direct children of the real OPC roots, never nested decoys.
  if (typesRoot.localName !== 'Types' || typesRoot.namespaceURI !== CONTENT_TYPES_NAMESPACE ||
    relsRoot.localName !== 'Relationships' || relsRoot.namespaceURI !== RELATIONSHIPS_NAMESPACE) invalid(`${label} contains invalid package roots`);
  // Inspect decoded MIME values: XLM macro sheets need not have macro-looking part names.
  if ([...typesRoot.children].some(node => /macroEnabled|vbaProject|vbaData|(?:intl)?macrosheet\+xml/i.test(node.getAttribute('ContentType') ?? ''))) invalid(`${label} macros are not allowed`);
  if (!hasMainOverride(typesRoot, spec) || !hasOfficeDocumentRelationship(relsRoot, spec) || !isOfficeMainRoot(document!.documentElement, spec)) invalid(`${label} is missing its required ${spec.label} package members`);
}

/** Use the installed XML parser rather than treating marker strings inside an arbitrary ZIP as
 * an Office package. Parsing detached XML runs no scripts and performs no network requests. */
async function validateOfficePackage(required: { members: ReadonlyMap<string, string>; extension: OfficeExtension },
  _optional: Record<string, never> = {}): Promise<void> {
  const spec = OFFICE_PACKAGES[required.extension];
  const label = required.extension.toUpperCase();
  const sources = ['[Content_Types].xml', '_rels/.rels', spec.part].map(name => required.members.get(name) ?? '');
  if (sources.some(xml => /<!DOCTYPE|<!ENTITY|macroEnabled|vbaProject/i.test(xml))) invalid(`${label} DTDs, entities and macros are not allowed`);
  const { JSDOM } = await loadOptionalPeer({ feature: 'Server-side HTML and SVG processing', dependency: 'jsdom', load: () => import('jsdom') });
  const window = new JSDOM('').window;
  try {
    assertOfficeXml({ documents: sources.map(source => new window.DOMParser().parseFromString(source, 'application/xml')), spec, label });
  } finally { window.close(); }
}

const OLE_SIGNATURE = Buffer.from([0xd0, 0xcf, 0x11, 0xe0, 0xa1, 0xb1, 0x1a, 0xe1]);
/** Byte-signature policies for download-only and PDF formats, keyed by extension. */
const SIGNATURE_CHECKS: Partial<Record<keyof typeof DOCUMENT_CONTENT_TYPES, (required: { bytes: Uint8Array }) => void>> = {
  doc: ({ bytes }) => { if (!Buffer.from(bytes.subarray(0, 8)).equals(OLE_SIGNATURE)) invalid("This file isn't a valid Word file."); },
  xls: ({ bytes }) => { if (!Buffer.from(bytes.subarray(0, 8)).equals(OLE_SIGNATURE)) invalid("This file isn't a valid Excel file."); },
  rtf: ({ bytes }) => { if (Buffer.from(bytes.subarray(0, 5)).toString('latin1') !== '{\\rtf') invalid("This file isn't a valid RTF file."); },
  pdf: ({ bytes }) => {
    // latin1 preserves high bits: ASCII decoding would turn counterfeit bytes into a valid header.
    const header = Buffer.from(bytes.subarray(0, 8)).toString('latin1');
    if (!/^%PDF-(?:1\.[0-7]|2\.0)/u.test(header)) invalid('document bytes do not have a PDF signature');
  },
};

function assertDocumentText({ bytes, contentType }: { bytes: Uint8Array; contentType: string }): void {
  const text = decodeDocumentUtf8({ bytes });
  if (contentType !== DOCUMENT_CONTENT_TYPES.json) return;
  try { JSON.parse(text.replace(/^\uFEFF/u, '')); } catch { invalid('document JSON is invalid'); }
}

/** Extension selects a policy; actual bytes must satisfy it. Client MIME never grants admission.
 * Throws MediaValidationError before persistence; O(bytes) work/space, capped at 50 MiB input
 * and 40 MiB expanded archive data. Legacy OLE/RTF checks identify formats, not malware. */
export async function validateDocumentIngress(required: { filename: string; bytes: Uint8Array },
  optional: { archiveReader?: DocumentArchiveReaderPort | undefined } = {}): Promise<{ contentType: string }> {
  if (!required.bytes.byteLength || required.bytes.byteLength > MAX_DOCUMENT_BYTES) invalid(`document must be non-empty and at most ${MAX_DOCUMENT_BYTES / (1024 * 1024)} MiB`);
  const contentType = documentContentType({ filename: required.filename });
  const extension = required.filename.slice(required.filename.lastIndexOf('.') + 1).toLowerCase();
  const signatureCheck = SIGNATURE_CHECKS[extension as keyof typeof DOCUMENT_CONTENT_TYPES];
  if (isArchiveExtension(extension)) await validateDocumentArchive({ bytes: required.bytes, extension, ...optional });
  else if (signatureCheck) signatureCheck({ bytes: required.bytes });
  else assertDocumentText({ bytes: required.bytes, contentType });
  return { contentType };
}

/** Preserve the immutable extension while the editable title supplies the display-name stem. */
export function documentDisplayFilename(required: { title: string; originalFilename?: string | null | undefined },
  _optional: Record<string, never> = {}): string {
  const original = required.originalFilename ?? '';
  return required.title + (original.includes('.') ? original.slice(original.lastIndexOf('.')) : '');
}

import { nowIso as kernelNowIso } from "@jini-ai/core/primitives";
/**
 * @file Write-service for the `navigation` library.
 *
 * Purpose:
 * Implements the menu mutation slice: create, whole-tree update (OCC), soft
 * delete → hard purge, and location assignment. Mirrors the host's `post`
 * feature style (required/optional param objects, typed errors, OCC via
 * `version`).
 *
 * How it relates to the project:
 * - Storage is `MenuRepoPort` (`repo.memory.ts`) — a self-contained repo, not
 * the generic entries repo (see `repo.memory.ts`'s file header for why).
 * - Location assignment additionally writes `NavLocationBindingRepoPort`
 * (`ports.ts`), the one real port this library declares.
 * - In production this whole module runs inside the command
 * gateway/write chokepoint (same-transaction revision, attribution,
 * `entry_refs` extraction). That gateway is not implemented as running code
 * yet, so these functions are the chokepoint's future *contents* called
 * directly for now.
 *
 * Architectural role:
 * Feature logic only. No Express/route code, no direct SQL — everything goes
 * through the injected repo ports (`deps`).
 */ 
import { assertEntityLive } from "../core/entity-liveness.js";
import type { Clock, IdGenerator, UUID } from "@jini-ai/core/primitives";
import type { DomainEvent, OutboxPort } from "../core/ports.js";
import type { MenuRepoPort } from "./repo.memory.js";
import type { NavLocationBindingRepoPort } from "./ports.js";
import { normalizeMenuItemAttrs } from "./link-rel.js";
import { menuHtmlInputProblem, mergeMenuHtml, type MenuHtmlAuthoring, type MenuHtmlNormalizer } from "./menu-html.js";
import {
  NAV_DOC_TYPE,
  type NavEntryTarget,
  type NavItemNode,
  type NavLocationBindingRow,
  type NavLocationKey,
  type NavMenuDoc,
  type NavMenuEntry,
  type NavMenuMode,
  type NavTarget,
  type NavUrlTarget,
} from "./types.js";

// ---------------------------------------------------------------------------
// Outbox event publication — each mutating function below
// enqueues its matching NAVIGATION_EVENTS entry after its repo write(s)
// succeed, never on a rejection path. Mirrors the host's proven
// `outbox.enqueue` call shape.
// ---------------------------------------------------------------------------

/**
 * `payload` is typed as a plain `Record<string, unknown>` (not the specific
 * `NavMenuChangedPayload`/`NavLocationChangedPayload` shape) so the result
 * assigns directly to `OutboxPort.enqueue`'s `DomainEvent` parameter (whose
 * default payload type is `Record<string, unknown>`) without a cast — every
 * call site below still passes a fresh object literal matching one of those
 * two contract shapes exactly (`contracts.ts`), just not nominally typed here.
 */ 
async function enqueueEvent(required: {
  deps: { idGen: IdGenerator; clock: Clock; outbox: OutboxPort };
  name: string;
  workspaceId: UUID;
  aggregateId: UUID;
  payload: Record<string, unknown>;
}): Promise<void> {
  const { deps } = required;
  const event: DomainEvent = {
    id: deps.idGen.newId(),
    name: required.name,
    occurredAt: kernelNowIso({ clock: deps.clock }),
    aggregateId: required.aggregateId,
    workspaceId: required.workspaceId,
    payload: required.payload,
  };
  await deps.outbox.enqueue(event);
}

// ---------------------------------------------------------------------------
// Typed errors
// ---------------------------------------------------------------------------

export class MenuNotFoundError extends Error {
  constructor({ message }: { message: string }, optionalArgs: ErrorOptions = {}) {
    super(message, optionalArgs);
  }
}
export class MenuValidationError extends Error {
  constructor({ message }: { message: string }, optionalArgs: ErrorOptions = {}) {
    super(message, optionalArgs);
  }
}
export class MenuConflictError extends Error {
  constructor({ message }: { message: string }, optionalArgs: ErrorOptions = {}) {
    super(message, optionalArgs);
  }
}

/**
 * A menu write lost its version check: the basis the caller read is no longer the stored live row's
 * version (or a create found the id taken). A subclass, so every `instanceof MenuConflictError` check
 * keeps matching, while a host can tell "someone else changed this, reload" apart from the other
 * conflicts (slug already taken, slug held by a trashed menu), which want the message itself.
 * Every `MenuRepoPort` adapter throws it, built by {@link menuVersionConflictError}.
 */
export class MenuVersionConflictError extends MenuConflictError {}

/** The version-check loss every `MenuRepoPort` adapter (and `updateMenuTree`'s read check) throws, one
 *  wording for all of them. `expectedVersion: null` is a create (`MenuSaveOptions`) that found the id taken. */
export function menuVersionConflictError(required: { id: UUID; expectedVersion: number | null; found: number | null }): MenuVersionConflictError {
  if (required.expectedVersion === null) {
    return new MenuVersionConflictError({ message: `menu '${required.id}' already exists (expected no menu, found version ${required.found ?? "none"})` });
  }
  return new MenuVersionConflictError({ message: `menu '${required.id}' was modified concurrently (expected version ${required.expectedVersion}, found ${required.found ?? "none"})` });
}

/**
 * The 409-style purge rejection: hard delete is blocked while the menu is
 * still bound to at least one theme location (deletion ladder).
 * Carries the offending location keys so a caller can render "unassign these
 * first" without a second lookup.
 */ 
export class MenuLocationBoundError extends MenuConflictError {
  readonly boundLocations: readonly NavLocationKey[];

  constructor(requiredArgs: { message: string; boundLocations: readonly NavLocationKey[] }, optionalArgs: Record<string, never> = {}) {
    const { message, boundLocations } = requiredArgs;
    super({ message: message });
    this.boundLocations = boundLocations;
  }
}

// ---------------------------------------------------------------------------
// Tree validation (total/bounded amendment)
// ---------------------------------------------------------------------------

/** Default max nesting depth (root = depth 1). Configurable. */ 
export const DEFAULT_MAX_TREE_DEPTH = 5;
/** Default max total item count across the whole tree. */ 
export const DEFAULT_MAX_ITEM_COUNT = 500;

const VALID_TARGET_KINDS = new Set<string>(["entryRef", "termRef", "url", "route"]);
/** Named deferred seams — recognized, rejected until their resolver ships. */ 
const RESERVED_TARGET_KINDS = new Set<string>(["dynamicQuery", "content"]);

/**
 * Fixed placeholder origin {@link isAllowedHref} resolves a claimed same-origin-relative href
 * against, to compare the RESOLVED origin rather than the raw string shape. Mirrors
 * the host's public renderer's identically-named constant
 * byte-for-byte — see that file's own header for why a fixed placeholder origin is sufficient (only
 * the relationship between the resolved URL's origin and this one is ever inspected, never the
 * placeholder value itself).
 */ 
// eslint-disable-next-line sonarjs/no-clear-text-protocols -- Reserved .invalid sentinel used only for URL parsing and origin comparison; no request is made.
const SAFE_HREF_RESOLUTION_BASE = "http://safehref.invalid/";
const SAFE_HREF_RESOLUTION_ORIGIN = new URL(SAFE_HREF_RESOLUTION_BASE).origin;

/**
 * The CANONICAL href allowlist for an author-authored link — same accepted shapes (`#…`, same-origin
 * `/…`, `http(s)://`, `mailto:`) as the host's render-time `safeHref` in `render.ts` and its
 * `features/theme/static-render.ts` duplicate. **This is now the single source of truth** exported
 * from this package's public surface (`navigation/index.ts` -> `@jini-ai/cms/navigation`) so the
 * dependency runs the direction that is actually legal — the host already depends on `@jini-ai/cms`, not
 * the reverse — rather than each consumer hand-copying the predicate.
 *
 * The two host-side copies (`render.ts:252`, `features/theme/static-render.ts:210`, both a coercing
 * `value => passes ? value : "#"` wrapper around the identical predicate below) have **not yet been
 * retired to import this** — that edit is intentionally out of this change's scope (a
 * `check:boundaries` no-deep-import concern is NOT what blocks it: `render.ts` already imports
 * `@jini-ai/cms/core` today, and `features/theme` already imports `@jini-ai/cms/core` too, so both
 * call sites may legally import `@jini-ai/cms/navigation` directly — verified by grep, not assumed).
 * Until that follow-up lands, the host's menu href allowlist sync check
 * behaviorally gates the three copies against the same adversarial table so a divergence fails CI
 * instead of drifting silently.
 *
 * Replaced (this change) a `URL_SCHEME_DENYLIST` (`startsWith` on a lowercased, `.trim`ed string)
 * that failed open: the WHATWG `URL` parser strips TAB/LF/CR from ANYWHERE in the input and folds a
 * leading backslash to `/` for `http(s)`, so `"java\tscript:alert"`, `" javascript:alert"`,
 * `"file:// etc/passwd"`, `"blob:…"`, `"about:blank"`, `"//evil.example"` (protocol-relative), and
 * `"/\evil.example"` all resolved to a dangerous or off-origin target while never matching any
 * `startsWith` prefix in the old list. An allowlist closes the whole bypass class at once (case,
 * embedded control characters, and scheme are all irrelevant to an allowlist the same way) rather
 * than needing a new prefix bolted on per newly-discovered shape.
 *
 * `validateTarget`'s caller REJECTS on a `false` result (`MenuValidationError`, surfaced as HTTP 400)
 * rather than silently coercing the way `safeHref`'s render-time callers degrade to `"#"` — a
 * write-time author-facing path should say so, not quietly rewrite the input. Verified against the
 * workspace's stored menu data (`content.db`, `content.seed.db`) before this change: every existing
 * `url`-kind href already starts with `#` or `/`, so this tightening rejects nothing that exists
 * today — it governs `createMenu` too, so it also reaches the Jini MCP agent-tool path, not just
 * hrefs written through the host's admin editor.
 *
 * @param rawHref - The href to check, already confirmed non-empty by `validateTarget`. Any string is
 * otherwise a valid input — this function performs no other precondition checks.
 * @returns `true` when `rawHref` passes the allowlist, `false` otherwise.
 * @complexity O — a handful of string checks plus one `URL` construction on the `/…` branch.
 */ 
export function isAllowedHref({ rawHref }: { rawHref: string }, _optional: Record<string, never> = {}): boolean {
  const href = rawHref.trim();
  if (href.startsWith("#")) return true;
  if (/^https?:\/\//i.test(href) || /^mailto:/i.test(href)) return true;
  if (href.startsWith("/")) {
    try {
      return new URL(href, SAFE_HREF_RESOLUTION_BASE).origin === SAFE_HREF_RESOLUTION_ORIGIN;
    } catch {
      return false;
    }
  }
  return false;
}

/**
 * Human-readable description of {@link isAllowedHref}'s accepted shapes — the single source of truth
 * for both `validateTarget`'s rejection message below and `agent-tools.ts`'s published JSON Schema
 * `href` description, so an author-facing 400 and an LLM-facing tool description can never drift out
 * of sync with each other the way three independent copies of the URL-checking LOGIC itself did
 * before this change.
 */ 
export const ALLOWED_HREF_SHAPES_DESCRIPTION =
  "an in-page anchor ('#...'), a same-origin relative path ('/...'), an 'http://' or 'https://' URL, or a 'mailto:' address";

export interface TreeValidationLimits {
  maxDepth?: number | undefined;
  maxItemCount?: number | undefined;
}

/**
 * Validates a candidate item tree and returns a defensively-cloned copy.
 *
 * Checks (total/bounded validation + target integrity):
 * - `items` (and every `children` array) is actually an array, and every node
 * in it is a non-null object — untrusted JSON bodies can carry `null`
 * entries or a non-array `items`/`children`, which must reject as a
 * `MenuValidationError`, not throw an uncaught `TypeError`;
 * - every node has a non-empty `id`, unique across the whole tree (id
 * stability is a caller responsibility — see `updateMenuTree` doc for the
 * simplification this build accepts);
 * - nesting depth stays within `maxDepth`;
 * - total item count stays within `maxItemCount`;
 * - every node has a `target` object (a missing/`null` `target` rejects
 * rather than crashing) whose `kind` is one of the four v1 kinds — reserved
 * kinds (`dynamicQuery`, `content`) are rejected with a clear "not yet"
 * error rather than silently accepted;
 * - `url` targets require a non-empty string `href` and pass an origin/scheme
 * ALLOWLIST (`#…`, same-origin `/…`, `http(s)://`, `mailto:` — see
 * {@link isAllowedHref}), not a scheme denylist.
 *
 * @complexity O(n) over total node count for one full walk; no per-node
 * backtracking. Space is O(n) for the cloned tree plus O(n) for the id set.
 * @overallScore 100
 */ 
export function validateAndCloneTree(
  { items }: { items: readonly NavItemNode[] },
  limits: TreeValidationLimits = {}
): NavItemNode[] {
  const maxDepth = limits.maxDepth ?? DEFAULT_MAX_TREE_DEPTH;
  const maxItemCount = limits.maxItemCount ?? DEFAULT_MAX_ITEM_COUNT;
  const seenIds = new Set<string>();
  let count = 0;

  function walk(nodes: readonly NavItemNode[], depth: number): NavItemNode[] {
    if (!Array.isArray(nodes)) {
      throw new MenuValidationError({ message: "menu items must be an array" });
    }
    if (depth > maxDepth) {
      throw new MenuValidationError({ message: `menu tree exceeds max nesting depth of ${maxDepth}` });
    }
    return nodes.map((node) => {
      count += 1;
      if (count > maxItemCount) {
        throw new MenuValidationError({ message: `menu tree exceeds max item count of ${maxItemCount}` });
      }
      if (!node || typeof node !== "object") {
        throw new MenuValidationError({ message: "every menu item must be an object" });
      }
      if (!node.id || !node.id.trim()) {
        throw new MenuValidationError({ message: "every menu item requires a non-empty id" });
      }
      if (seenIds.has(node.id)) {
        throw new MenuValidationError({ message: `duplicate item id '${node.id}' in menu tree` });
      }
      seenIds.add(node.id);
      validateTarget(node.target);

      const children = node.children ? walk(node.children, depth + 1) : undefined;
      // `rel` is cleaned here, not rejected — see `link-rel.ts` for the policy.
      const attrs = normalizeMenuItemAttrs({ attrs: node.attrs });
      return { ...node, ...(attrs === undefined ? {} : { attrs }), children };
    });
  }

  return walk(items, 1);
}

/**
 * Guards every field this function reads off an untrusted `target` before reading it — a `target`
 * arriving `null`/`undefined` (missing from the request body) or a `url` target missing `href`
 * previously threw an uncaught `TypeError` here, which the host's route handler had no case for and
 * surfaced as a 500 instead of the intended 400 `MenuValidationError` path.
 */ 
function validateTarget(target: NavTarget): void {
  if (!target || typeof target !== "object") {
    throw new MenuValidationError({ message: "every menu item requires a target" });
  }
  assertSupportedTargetKind({ kind: target.kind });
  if (target.kind === "entryRef") assertAllowedEntryHintHref({ target });
  if (target.kind === "url") assertAllowedUrlHref({ target });
}

/** Reserved kinds get their own "not yet" message; anything else outside the four v1 kinds is unknown. */
function assertSupportedTargetKind({ kind }: { kind: string }): void {
  if (RESERVED_TARGET_KINDS.has(kind)) {
    throw new MenuValidationError({ message: `target kind '${kind}' is a reserved seam and is not supported yet` });
  }
  if (!VALID_TARGET_KINDS.has(kind)) {
    throw new MenuValidationError({ message: `unknown target kind '${kind}'` });
  }
}

/** An untrusted href field must be a string with non-whitespace content before {@link isAllowedHref} may read it. */
function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim() !== "";
}

/** `lastKnownHref` is an optional hint, so only a present one is checked — against the same allowlist as a `url` href. */
function assertAllowedEntryHintHref({ target }: { target: NavEntryTarget }): void {
  const rawHref: unknown = target.lastKnownHref;
  if (rawHref === undefined) return;
  if (!isNonEmptyString(rawHref) || !isAllowedHref({ rawHref })) {
    throw new MenuValidationError({ message: `entryRef lastKnownHref must be ${ALLOWED_HREF_SHAPES_DESCRIPTION}.` });
  }
}

function assertAllowedUrlHref({ target }: { target: NavUrlTarget }): void {
  const rawHref: unknown = target.href;
  if (!isNonEmptyString(rawHref)) {
    throw new MenuValidationError({ message: "url target requires a non-empty href" });
  }
  if (!isAllowedHref({ rawHref })) {
    throw new MenuValidationError({ message: `url target href is not allowed: '${rawHref}'. Accepted shapes: ${ALLOWED_HREF_SHAPES_DESCRIPTION}.` });
  }
}

/** Reads a menu the caller named by id; a missing one is the not-found refusal every mutation shares. */
async function findMenuOrThrow({ repo, workspaceId, id }: { repo: MenuRepoPort; workspaceId: UUID; id: UUID }): Promise<NavMenuEntry> {
  const menu = await repo.findById({ workspaceId, id });
  if (!menu) throw new MenuNotFoundError({ message: `menu '${id}' was not found` });
  return menu;
}

function assertMenuLive({ menu }: { menu: NavMenuEntry }): void {
  assertEntityLive({ entityType: "menu", entityId: menu.id, state: menu.status === "trash" ? "trashed" : "live" });
}

/**
 * Slugs are unique per workspace. `ownerId` is the menu being saved: its own row is not a conflict,
 * which matters when a store's slug lookup is looser than an exact match (a NOCASE collation) and
 * returns the menu itself for a slug that only differs by normalization.
 */
async function assertSlugAvailable(
  { repo, workspaceId, slug }: { repo: MenuRepoPort; workspaceId: UUID; slug: string },
  { ownerId }: { ownerId?: UUID | undefined } = {}
): Promise<void> {
  const duplicate = await repo.findBySlug({ workspaceId, slug });
  if (duplicate && duplicate.id !== ownerId) {
    throw new MenuConflictError({ message: `slug '${slug}' already exists` });
  }
}

function assertValidTitleAndSlug(title: string, slug: string): void {
  if (!title) throw new MenuValidationError({ message: "title is required" });
  if (!slug.match(/^[a-z0-9-]+$/)) {
    throw new MenuValidationError({ message: "slug must use lowercase letters, numbers, and dashes" });
  }
}

